SELECT match_post.id as matchPostId, match_post.match_date as matchDate, match_post.sport_category as sportCategory, club.id as clubId, club.image_url as imageUrl, club.club_name as clubName, club.university as university, club.region as region, match_post.location as location, club.manner_score as mannerScore FROM match_post JOIN club on club.id = match_post.home_club_id WHERE 1=1 AND match_post.deleted = false AND match_post.status = false
AND match_post.sport_category IN
#{sportCategory}
AND club.region IN
#{region}
AND match_post.match_date >= #{listReqDto.startDate}
AND match_post.match_date <= #{listReqDto.endDate}
AND (club.club_name LIKE CONCAT('%', #{listReqDto.keyword}, '%') OR club.university LIKE CONCAT('%', #{listReqDto.keyword}, '%') OR match_post.location LIKE CONCAT('%', #{listReqDto.keyword}, '%'))
ORDER BY match_post.match_date DESC, match_post.id DESC

